// Edit these if needed
const SECOND_DEGREE_FROM = '2026-01-01'; // from this date, searches show 2nd-degree people only
const WEEKLY_LIMIT = 100;
const TARGET_COMPANIES = ["Company One","Company Two","Company Three","Company Four"]; // one is picked per weekday
const LOCAL_SEARCH = 'Manchester software developer';

const UK = '%5B%22101165590%22%5D';
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/London' }));
const ymd = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const today = ymd(now);
const network = today >= SECOND_DEGREE_FROM ? '&network=%5B%22S%22%5D' : '';
const search = (keywords, ukOnly = true) =>
  'https://www.linkedin.com/search/results/people/?keywords=' + encodeURIComponent(keywords) +
  (ukOnly ? '&geoUrn=' + UK : '') + network + '&origin=FACETED_SEARCH';

const company = TARGET_COMPANIES[now.getDay() % TARGET_COMPANIES.length];

const segments = [
  ['Tech recruiters (AI)', 6, search('technical recruiter AI')],
  ['Recruitment consultants (automation)', 3, search('recruitment consultant automation')],
  ['n8n builders', 4, search('n8n')],
  ['AI automation engineers', 3, search('AI automation engineer')],
  ['Local tech', 2, search(LOCAL_SEARCH)],
  ['People at ' + company, 2, search(company, false)],
];

// Weekly count is shared with the reply branch through workflow static data
const data = $getWorkflowStaticData('global');
const monday = new Date(now);
monday.setDate(now.getDate() - ((now.getDay() + 6) % 7));
const weekKey = ymd(monday);
if (data.weekKey !== weekKey) { data.weekKey = weekKey; data.week = 0; }

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const target = Math.min(20, Math.max(0, WEEKLY_LIMIT - data.week));

let text;
if (target === 0) {
  text = 'Weekly limit reached (' + data.week + '/' + WEEKLY_LIMIT + '). No invites today.';
} else {
  text = [
    '<b>LinkedIn connections: ' + target + ' today</b>',
    'This week so far: ' + data.week + '/' + WEEKLY_LIMIT,
    '',
    ...segments.map(([label, n, url]) => '• <a href="' + esc(url) + '">' + esc(label) + '</a>: ' + n),
    '',
    'Only connect with relevant headlines. Reply with the number you sent.',
  ].join('\n');
}
return [{ json: { text } }];

const ALLOWED_CHAT_ID = 'PASTE_YOUR_CHAT_ID'; // only your chat can log counts
const WEEKLY_LIMIT = 100;

const msg = $input.first().json.message;
if (!msg || String(msg.chat.id) !== ALLOWED_CHAT_ID) return [];

const data = $getWorkflowStaticData('global');
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/London' }));
const ymd = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const monday = new Date(now);
monday.setDate(now.getDate() - ((now.getDay() + 6) % 7));
const weekKey = ymd(monday);
if (data.weekKey !== weekKey) { data.weekKey = weekKey; data.week = 0; }
data.total = data.total || 0;

const input = (msg.text || '').trim();
let reply;
if (/^\d{1,3}$/.test(input)) {
  const n = parseInt(input, 10);
  data.week += n;
  data.total += n;
  reply = 'Logged ' + n + '. This week: ' + data.week + '/' + WEEKLY_LIMIT + '. Total sent: ' + data.total + '.';
  if (data.week >= WEEKLY_LIMIT) reply += ' Weekly limit reached, stop until Monday.';
} else if (input === '/stats') {
  reply = 'This week: ' + data.week + '/' + WEEKLY_LIMIT + '. Total sent: ' + data.total + '.';
} else {
  reply = 'Send just a number (invites sent today), or /stats.';
}
return [{ json: { chatId: msg.chat.id, text: reply } }];
